def _serialise_lab(lab):
    """Convert Decimal values to float/int for JSON serialisation."""
    out = {}
    for k, v in lab.items():
        if isinstance(v, Decimal):
            # Preserve integer appearance for whole numbers
            out[k] = float(v)
        else:
            out[k] = v
    return out

