def main():
    args = sys.argv[1:]
    if not args:
        print(__doc__)
        sys.exit(1)

    cmd = args[0]
    flags = set(args[1:])

    if cmd == "update":
        cmd_update(quiet="--quiet" in flags)
    elif cmd == "status":
        cmd_status(as_json="--json" in flags)
    elif cmd == "detect-changes":
        cmd_detect_changes(brief="--brief" in flags)
    else:
        print(f"Unknown command: {cmd}", file=sys.stderr)
        sys.exit(1)

