def _node_summary(nid: str) -> dict | None:
    node = _nodes().get(nid)
    if not node:
        return None
    return {
        "id": nid,
        "type": node["type"],
        "name": node["name"],
        "file": os.path.relpath(node["file"], ROOT).replace("\\", "/"),
        "line": node["line"],
        "end_line": node["end_line"],
        "docstring": node.get("docstring", "")[:200],
    }

